 for u in U:
  if u['paperId']==p:
   sources.append(dict(id=u['id'],paperId=p,lens=u['lens'],text=u['text'],browserVectorRow=u['vectorRow'],sourceNodeIds=u['evidence']['sourceNodeIds'],evidenceRefs=u['evidence']['anchors'],sourceSha256=u['evidence']['sourceSha256'],sourceUrl='https://arxiv.org/abs/'+p))
