def add(id,title,question,summary,ps,includes,excludes,assumptions,regimes,methods,directions):
 ss=qs(ps);cards.append(dict(id=id,kind='question',title=title,question=question,summary=summary,scope=dict(includes=includes,excludes=excludes,assumptions=assumptions,regimes=regimes,conventions=['Different momentum symbols must be identified in the parent rest frame before comparing threshold scalings.'] if 'threshold' in id else []),evidenceIds=[s['id'] for s in ss],scientificStatus='source_read_question_draft; claims attributed; not independently validated',placementStatus='proposed; canonical identity awaiting challenge',methods=methods,readingLimit='This evaluation read archived primary text for 2209.09249 and 2311.05318 source anchors and p1 of 2609.36234/2610.01825. No fresh mathematical reproduction or image verification; secondary neighboring papers remain extraction-supported.',readingCoverage=dict(textReading='bounded_source_excerpts',fullPaper=False,images=False),provenance=dict(request='Q-025',author='atlas_scientific_evaluation',sourceReading='evaluation/geometry-critique.md',identityStatus='draft_not_accepted'),contributions=[dict(unitId=s['id'],role='addresses',sourceNodeIds=s['sourceNodeIds']) for s in ss],proposedDirections=directions))
add('q-kk-graviton-thermal-production','How is a KK-graviton population produced?','Can a hot Standard Model brane gravitationally produce the KK-graviton abundance needed in the Dark Dimension setting?','The source studies initially unexcited bulk modes coupled to a hot Standard Model brane. Initial production and abundance are a distinct question from whether the produced population can subsequently cascade rapidly enough to remain viable dark matter.',['2209.09249'],['brane-to-bulk production','initial tower population and abundance'],['late-time linear perturbation constraints as the primary target','all possible dark-sector production mechanisms'],['specified initial brane temperature','bulk initially essentially unexcited','gravitational coupling to the brane'],['Dark Dimension setup; source-specific cosmological assumptions'],['coupled production/evolution equations','parametric abundance estimates'],['q-kk-graviton-threshold-decay','q-kk-decay-linear-cosmology','q-flat-darkdimension-freezein-bounds'])
add('q-kk-graviton-threshold-decay','What controls the near-threshold cascade rate?','How does an intra-tower KK-graviton decay amplitude and rate scale with daughter momentum near threshold, and which background or coupling assumptions control that scaling?','Two late-2026 sources in the frozen corpus argue for stronger threshold suppression than assumed in earlier rapid-cascade estimates. One studies cancellations and their scope in scalar–gravity systems; the other emphasizes the partial-wave interpretation and applies it to a flat dark dimension. Their contribution to this common question does not require treating their entire claims or regimes as equivalent.',['2609.36234','2610.01825'],['parent and daughter KK gravitons','near-threshold momentum dependence','cancellation/partial-wave explanations and stated generality'],['unqualified universal statement for every field content or higher-derivative theory','automatic equivalence of all cosmological conclusions'],['five-dimensional gravitational setting','source-specific diffeomorphism-invariant couplings and background assumptions'],['near-threshold two-body decay; detailed paper-specific scope retained'],['explicit three-point amplitude','polarization/cancellation analysis','partial-wave analysis'],['q-kk-decay-linear-cosmology','q-flat-darkdimension-freezein-bounds','q-kk-graviton-thermal-production'])
add('q-kk-decay-linear-cosmology','What would repeated decays do to cosmological structure?','Within the specified repeated-decay KK-graviton model, how do daughter recoil and the changing mass distribution affect linear cosmological perturbations?','The 2023 analysis propagates a simplified decay-driven population through linear cosmology and constrains a kick-velocity combination. Its observational calculation should be read together with the assumed cascade dynamics. The later threshold-rate question tests a premise of the rapid-cascade scenario; it is a separate connected destination.',['2311.05318'],['linear perturbations','daughter recoil','changing KK-graviton mass population','source-era CMB/BAO/lensing constraints'],['new observational data beyond the frozen source','unconditional viability of the underlying cascade model','generic stable axion dark matter'],['assumed repeated intra-tower decay evolution','simplified nonrelativistic population/distribution'],['linear cosmological regime; dated source model and observations'],['Boltzmann/perturbation evolution','parameter inference'],['q-kk-graviton-threshold-decay','q-flat-darkdimension-freezein-bounds','q-kk-graviton-thermal-production'])
add('q-flat-darkdimension-freezein-bounds','What bounds survive if the cascade is suppressed?','In a flat dark dimension with threshold-suppressed KK-graviton cascades, what observational constraints follow from the irreducibly produced population even if it is not all dark matter?','The 2026 source studies photon emission from an unavoidable freeze-in population and compares the resulting upper reheating bound with lower cosmological bounds. This asks a different question from fitting linear structure in the earlier fast-cascade model. The stated flat-dimension scope must remain visible.',['2610.01825'],['irreducible production','visible decay products','reheating and radius constraints','subdominant KK population allowed'],['all extra-dimensional models excluded without a scope argument','unqualified replacement of every earlier cosmological calculation'],['flat dark dimension','near-threshold cascade suppression as argued in source','specified Standard Model brane coupling'],['source-specific freeze-in/decay cosmology and observational assumptions'],['freeze-in abundance','photon/energy-injection bounds','reheating-bound comparison'],['q-kk-graviton-threshold-decay','q-kk-graviton-thermal-production','q-kk-decay-linear-cosmology'])
aliases={'q-kk-graviton-thermal-production': ['How does the hot Standard Model brane populate the initially cold KK-graviton bulk?', 'What sets the initial KK-graviton abundance in the specified Dark Dimension brane cosmology?'], 'q-kk-graviton-threshold-decay': ['In the stated five-dimensional KK setting, what is the daughter-momentum scaling of intra-tower graviton decay near threshold?', 'Which cancellations or partial waves determine the near-threshold KK-graviton cascade rate under these coupling assumptions?'], 'q-kk-decay-linear-cosmology': ['For the assumed repeatedly decaying KK-graviton population, how do recoil kicks alter linear structure formation?', 'What linear CMB, BAO and lensing signatures follow from the specified KK-tower decay evolution?'], 'q-flat-darkdimension-freezein-bounds': ['Even if KK gravitons are subdominant, what bounds follow from their unavoidable production and visible decay in the stated flat model?', 'How do freeze-in photon constraints and lower reheating bounds restrict the flat Dark Dimension when the tower cascade is threshold-suppressed?']}
for d in cards:d['aliases']=aliases[d['id']]
