(HERE/'kk-question-card-drafts.json').write_text(json.dumps(dict(schemaVersion='q025-question-card-drafts/1',status='source_read_drafts_need_independent_scope_and_identity_challenge',sources=sources,destinations=cards,identityChallengeCases=identity_cases,importantBoundary='These four common questions collect distinct source contributions via addresses, not alias-equivalence of entire papers. No new accepted scientific implication or tension edge is asserted.'),indent=2)+'\n')
